local rayParams = RaycastParams.new()
rayParams.FilterType = Enum.RaycastFilterType.Exclude
rayParams.IgnoreWater = true

local ignoreCache = { list = {}, stamp = 0 }

local function baseIgnore()
    local now = os.clock()
    if now - ignoreCache.stamp > 0.15 then
        local list = {}
        local camera = workspace.CurrentCamera
        if camera then
            table.insert(list, camera)
        end
        for _, other in ipairs(Players:GetPlayers()) do
            if other.Character then
                table.insert(list, other.Character)
            end
        end
        ignoreCache.list = list
        ignoreCache.stamp = now
    end
    return ignoreCache.list
end

local function visibleFrom(origin, part)
    local base = baseIgnore()
    local ignore = table.move(base, 1, #base, 1, {})
    local target = part.Position
    for _ = 1, 12 do
        rayParams.FilterDescendantsInstances = ignore
        local result = workspace:Raycast(origin, target - origin, rayParams)
        if not result then
            return true
        end
        local hit = result.Instance
        local model = hit:FindFirstAncestorOfClass("Model")
        if model and model:FindFirstChildOfClass("Humanoid") then
            table.insert(ignore, model)
        elseif hit.Transparency >= 0.7 then
            table.insert(ignore, hit)
        else
            return false
        end
    end
    return false
end

local wallbang = { enabled = false, hooked = false }

local function enemyCharacters()
    local list = {}
    for _, other in ipairs(Players:GetPlayers()) do
        if other ~= LocalPlayer and other.Character then
            table.insert(list, other.Character)
        end
    end
    return list
end

local function shouldPierce(origin, length)
    local camera = workspace.CurrentCamera
    if not camera or length < 60 then
        return false
    end
    if (origin - camera.CFrame.Position).Magnitude <= 15 then
        return true
    end
    local character = LocalPlayer.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    return root ~= nil and (origin - root.Position).Magnitude <= 15
end

local function installWallbang()
    if wallbang.hooked then
        return true
    end
    if not (hookmetamethod and getnamecallmethod) then
        return false
    end
    local old
    local function handler(self, ...)
        local method = getnamecallmethod()
        if wallbang.enabled and self == workspace and not (checkcaller and checkcaller()) then
            if method == "Raycast" then
                local origin, direction = ...
                if typeof(origin) == "Vector3" and typeof(direction) == "Vector3" and shouldPierce(origin, direction.Magnitude) then
                    local params = RaycastParams.new()
                    params.FilterType = Enum.RaycastFilterType.Include
                    params.FilterDescendantsInstances = enemyCharacters()
                    params.IgnoreWater = true
                    return old(self, origin, direction, params)
                end
            elseif method == "FindPartOnRay" or method == "FindPartOnRayWithIgnoreList" or method == "FindPartOnRayWithWhitelist" then
                local ray = ...
                if typeof(ray) == "Ray" and shouldPierce(ray.Origin, ray.Direction.Magnitude) then
                    return workspace.FindPartOnRayWithWhitelist(workspace, ray, enemyCharacters())
                end
            end
        end
        return old(self, ...)
    end
    old = hookmetamethod(game, "__namecall", newcclosure and newcclosure(handler) or handler)
    wallbang.hooked = true
    return true
end

local IMAGE_DATA = ""

local B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function decode(data)
    data = data:gsub("[^" .. B64 .. "=]", "")
    return (data:gsub(".", function(x)
        if x == "=" then
            return ""
        end
        local r, f = "", (B64:find(x, 1, true) - 1)
        for i = 6, 1, -1 do
            r = r .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
        end
        return r
    end):gsub("%d%d%d?%d?%d?%d?%d?%d?", function(x)
        if #x ~= 8 then
            return ""
        end
        local c = 0
        for i = 1, 8 do
            c = c + (x:sub(i, i) == "1" and 2 ^ (8 - i) or 0)
        end
        return string.char(c)
    end))
end

local function loadImage()
    local ok, result = pcall(function()
        if writefile and getcustomasset then
            if not (isfile and isfile(IMAGE_FILE)) then
                writefile(IMAGE_FILE, decode(IMAGE_DATA))
            end
            return getcustomasset(IMAGE_FILE)
        end
    end)
    if ok and result then
        return result
    end
    return ""
end

local imageSource = loadImage()

local PIXELS = ""
local GRID_W = 30
local GRID_H = 20

local function buildPixelBackground(parent)
    parent.ClipsDescendants = true
    for row = 0, GRID_H - 1 do
        local keys = {}
        for k = 0, 14 do
            local r, g, b = 0, 0, 0
            for n = 0, 1 do
                local i = row * GRID_W + k * 2 + n
                local hex = PIXELS:sub(i * 6 + 1, i * 6 + 6)
                r = r + tonumber(hex:sub(1, 2), 16)
                g = g + tonumber(hex:sub(3, 4), 16)
                b = b + tonumber(hex:sub(5, 6), 16)
            end
            keys[#keys + 1] = ColorSequenceKeypoint.new(k / 14, Color3.fromRGB(math.floor(r / 2), math.floor(g / 2), math.floor(b / 2)))
        end
        local line = make("Frame", {
            Size = UDim2.new(1, 0, 1 / GRID_H, 1),
            Position = UDim2.new(0, 0, row / GRID_H, 0),
            BackgroundColor3 = Color3.new(1, 1, 1),
            BorderSizePixel = 0,
        }, parent)
        make("UIGradient", { Color = ColorSequence.new(keys) }, line)
    end
end

