local function aimParts(character)
    local list = {}
    local head = character:FindFirstChild("Head")
    local body = character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso") or character:FindFirstChild("HumanoidRootPart")
    if aim.mode ~= "body" and head then
        table.insert(list, head)
    end
    if aim.mode ~= "head" and body then
        table.insert(list, body)
    end
    return list
end

local function findTarget(cam)
    local center = cam.ViewportSize / 2
    local bestPart, bestName, bestDist
    for _, player in ipairs(Players:GetPlayers()) do
        local character = player ~= LocalPlayer and player.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        if humanoid and humanoid.Health > 0 then
            for _, part in ipairs(aimParts(character)) do
                local pos, onScreen = cam:WorldToViewportPoint(part.Position)
                if onScreen then
                    local dist = (Vector2.new(pos.X, pos.Y) - center).Magnitude
                    if dist <= aim.fov and (not aim.wall or visibleFrom(cam.CFrame.Position, part)) then
                        if not bestDist or dist < bestDist then
                            bestPart, bestName, bestDist = part, player.DisplayName, dist
                        end
                        break
                    end
                end
            end
        end
    end
    return bestPart, bestName
end

RunService:BindToRenderStep("KenAim", Enum.RenderPriority.Camera.Value + 1, function(dt)
    if not aim.enabled then
        return
    end
    local cam = workspace.CurrentCamera
    if not cam then
        return
    end
    local part, name = findTarget(cam)
    if part then
        local goal = CFrame.lookAt(cam.CFrame.Position, part.Position)
        local alpha = 1 - (1 - 1 / aim.smooth) ^ (dt * 60)
        cam.CFrame = cam.CFrame:Lerp(goal, math.clamp(alpha, 0, 1))
        aimStatus.Text = "Khóa: " .. name .. (part.Name == "Head" and " • Đầu" or " • Thân")
        aimStatus.TextColor3 = GREEN
    else
        aimStatus.Text = "Đang tìm mục tiêu"
        aimStatus.TextColor3 = MUTED
    end
end)

