    local angle = math.random() * math.pi * 2
    local radius = math.random(3, 12)
    humanoid:MoveTo(afk.origin + Vector3.new(math.cos(angle) * radius, 0, math.sin(angle) * radius))
    if math.random() < 0.3 then
        humanoid.Jump = true
    end
end))

